let lang='es';
const artists=[{name:'NARA VOSS',type:'HYPNOTIC HOUSE',es:'Selección conceptual: bajos profundos, percusión rota y una sesión que no mira el reloj.',en:'Concept selection: deep bass, broken percussion and a set that loses track of time.'},{name:'SAL NEGRA',type:'LIVE / ALT ROCK',es:'Selección conceptual: guitarras crudas y un directo sin filtro. Un cambio de frecuencia.',en:'Concept selection: raw guitars and an unfiltered live show. A change of frequency.'},{name:'CORA SUR',type:'REGGAETON / CLUB',es:'Selección conceptual: ritmos latinos y electrónica que se encuentran a mitad de la pista.',en:'Concept selection: Latin rhythms and electronic sounds meet halfway across the floor.'},{name:'DUST RADIO',type:'COUNTRY / LIVE',es:'Selección conceptual: cuerdas, polvo y canciones para un horizonte abierto.',en:'Concept selection: strings, dust and songs for an open horizon.'},{name:'MILO TIDE',type:'ELECTRO / TECHNO',es:'Selección conceptual: texturas analógicas y pulsos eléctricos hasta la última señal.',en:'Concept selection: analogue textures and electric pulses until the final signal.'}];
function renderArtists(){document.getElementById('artist-list').innerHTML=artists.map((a,i)=>`<button class="artist-row" aria-expanded="false" aria-controls="artist-${i}" data-artist="${i}"><span class="num">0${i+1}</span><span class="artist-name">${a.name}</span><span class="artist-type">${a.type}</span><span class="plus">+</span></button><p class="artist-detail" id="artist-${i}" hidden>${a[lang]}</p>`).join('');document.querySelectorAll('[data-artist]').forEach(b=>b.onclick=()=>{const open=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!open));document.getElementById(b.getAttribute('aria-controls')).hidden=open;b.querySelector('.plus').textContent=open?'+':'−';});}
function translate(){document.documentElement.lang=lang;document.querySelectorAll('[data-es]').forEach(e=>e.innerHTML=e.dataset[lang]);const b=document.getElementById('language');b.innerHTML=lang==='es'?'ES <span>/ EN</span>':'<span>ES /</span> EN';b.setAttribute('aria-label',lang==='es'?'Switch to English':'Cambiar a español');document.title=lang==='es'?'BOIA — Festival underground':'BOIA — Underground music festival';document.querySelector('meta[name="description"]').content=lang==='es'?'BOIA. Festival underground. Electrónica, directo y artistas sin fronteras. Próxima fecha: próximamente.':'BOIA. Underground music festival. Electronic music, live acts and artists without borders. Next edition coming soon.';renderArtists();}
document.getElementById('language').onclick=()=>{lang=lang==='es'?'en':'es';translate();};translate();
const modal=document.getElementById('lightbox'),content=document.getElementById('modal-content'),caption=document.getElementById('modal-caption');document.querySelectorAll('[data-poster]').forEach(b=>b.onclick=()=>{const clone=b.cloneNode(true);clone.removeAttribute('data-poster');clone.setAttribute('tabindex','-1');content.replaceChildren(clone);caption.textContent=lang==='es'?'Cartel conceptual BOIA. Edición ficticia para esta primera propuesta.':'BOIA concept poster. Fictional edition for this first proposal.';modal.showModal();});document.querySelectorAll('[data-gallery]').forEach(b=>b.onclick=()=>{content.replaceChildren(b.querySelector('img').cloneNode());caption.textContent=lang==='es'?'Visual generado para BOIA. No documenta un evento real.':'Visual generated for BOIA. Not a photograph of a real event.';modal.showModal();});document.getElementById('close-modal').onclick=()=>modal.close();modal.onclick=e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close();}};
if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.remove('pending');observer.unobserve(e.target);}}),{threshold:.1});document.querySelectorAll('h2,.reveal').forEach(e=>{e.classList.add('reveal','pending');observer.observe(e);});}
